'use client'

import { useStrings, type StringsOverrides } from './strings'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Chart, and `tsc --noEmit` passes on it, so the
// gate cannot catch it.
import './chart.css'

/**
 * Chart: bars, lines, areas and rings, drawn in SVG by hand.
 *
 * GSUI-287. The shapes follow shadcn's charts (grouped and stacked bars, a
 * gradient area, lines with dots or steps, radial progress and a stacked
 * radial, a tooltip, a legend) but nothing here is a charting library: a game
 * page has a load budget, and four chart types are a few hundred lines of
 * geometry, not a dependency.
 *
 * **Colour is a token, never a value.** A series names a tone, the tone is a
 * `--gs-color-*-solid` token, and the Studio palette bridge rewrites those
 * tokens, so a chart follows a game's palette without knowing it has one.
 *
 * **Every chart is also a table.** A screen reader gets a visually hidden table
 * of the same numbers; the drawing itself is `aria-hidden`. The plot is one
 * focusable group: arrow keys move between points, and the point in focus is
 * announced and shown in the tooltip, so nothing is hover-only.
 *
 * **It moves once, on mount, and never under reduced motion.** Bars grow from
 * the baseline, lines draw, areas rise and rings sweep, all as transitions on
 * the fill motion token. The drawn elements carry `data-gs-animates="motion"`,
 * which the token file stops dead under reduced motion.
 *
 * It performs nothing: the host supplies the numbers and the words.
 */

export type ChartType = 'bar' | 'line' | 'area' | 'radial'

/** The colour roles a series may take. Each is a token the palette bridge reaches. */
export type ChartTone =
  | 'interactive'
  | 'reward'
  | 'positive'
  | 'player'
  | 'opponent'
  | 'warning'
  | 'negative'
  | 'muted'

export interface ChartSeries {
  /** The data key this series reads from each row. */
  key: string
  /** The word a player reads for it, in the legend, tooltip and table. */
  label: string
  /** Its colour role. Defaults cycle through player, reward, positive, opponent, warning. */
  tone?: ChartTone
}

export type ChartRow = Record<string, string | number>

export interface ChartProps extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides
  type: ChartType
  /** One row per point on the x axis; for `radial`, the first row holds each ring's value. */
  data: ChartRow[]
  /** The key holding each row's category, e.g. `round`. Not used by `radial`. */
  x?: string
  series: ChartSeries[]
  /** What the chart shows, as a player would say it. Its accessible name. */
  label: string
  /** Stack series on each other rather than side by side (bars, areas, one radial ring). */
  stacked?: boolean
  /** How a line or area joins its points. */
  curve?: 'linear' | 'smooth' | 'step'
  /** Draw a dot on every point of a line. */
  dots?: boolean
  /** The top of the scale. For `radial`, what a full ring means. Defaults to the data's maximum. */
  max?: number
  /** Render a number as a player reads it, e.g. `1,500` or `72%`. */
  format?: (value: number) => string
  /** Show the legend. Defaults to on when there is more than one series. */
  legend?: boolean
  /** Plot height in pixels. Width fills the container. */
  height?: number
  /** What sits in the middle of a radial chart, e.g. a Stat. Never announced. */
  center?: React.ReactNode
}

// The order a chart falls back to. Led by tones that differ in every theme:
// stadium draws interactive and reward in the same gold, and paper draws
// interactive and player in two close blues, so neither pair leads.
const DEFAULT_TONES: ChartTone[] = ['player', 'reward', 'positive', 'opponent', 'warning']

const toneVar = (tone: ChartTone) => `var(--gs-color-${tone}-solid)`

const numberFormat = new Intl.NumberFormat(undefined, { maximumFractionDigits: 1 })

/** Three to five round steps from zero to at least `top`. */
function niceTicks(top: number): number[] {
  if (!(top > 0)) return [0, 1]
  const rough = top / 4
  const magnitude = 10 ** Math.floor(Math.log10(rough))
  const step = [1, 2, 2.5, 5, 10].map((m) => m * magnitude).find((s) => s >= rough) ?? rough
  const ticks: number[] = []
  for (let t = 0; t <= top + step * 0.001; t += step) ticks.push(Number(t.toFixed(6)))
  const last = ticks[ticks.length - 1] ?? 0
  if (last < top) ticks.push(last + step)
  return ticks
}

/** A path through points. Smooth is a monotone-ish cubic; step holds each value to the next point. */
function linePath(points: Array<[number, number]>, curve: ChartProps['curve']): string {
  const [first, ...rest] = points
  if (!first) return ''
  let d = `M${first[0]},${first[1]}`
  rest.forEach((point, i) => {
    const previous = points[i] ?? first
    if (curve === 'step') {
      d += `H${point[0]}V${point[1]}`
    } else if (curve === 'smooth') {
      const mid = (previous[0] + point[0]) / 2
      d += `C${mid},${previous[1]} ${mid},${point[1]} ${point[0]},${point[1]}`
    } else {
      d += `L${point[0]},${point[1]}`
    }
  })
  return d
}

/** An arc of a circle as a path, from `start` to `end` as fractions of a turn from twelve o'clock. */
function arcPath(cx: number, cy: number, r: number, start: number, end: number): string {
  const angle = (f: number) => f * 2 * Math.PI - Math.PI / 2
  const sweep = Math.min(end - start, 0.9999)
  const [x1, y1] = [cx + r * Math.cos(angle(start)), cy + r * Math.sin(angle(start))]
  const [x2, y2] = [cx + r * Math.cos(angle(start + sweep)), cy + r * Math.sin(angle(start + sweep))]
  return `M${x1},${y1}A${r},${r} 0 ${sweep > 0.5 ? 1 : 0} 1 ${x2},${y2}`
}

/** The container's width, followed as it changes. 320 until measured, and in environments that cannot measure. */
function useWidth(ref: React.RefObject<HTMLDivElement | null>): number {
  const [width, setWidth] = React.useState(320)
  React.useLayoutEffect(() => {
    const element = ref.current
    if (!element || typeof ResizeObserver === 'undefined') return
    const observer = new ResizeObserver(([entry]) => {
      if (!entry) return
      const next = Math.round(entry.contentRect.width)
      if (next > 0) setWidth(next)
    })
    observer.observe(element)
    return () => observer.disconnect()
  }, [ref])
  return width
}

export function Chart(props: ChartProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)
  const {
    type,
    data,
    x,
    series,
    label,
    stacked = false,
    curve = 'linear',
    dots = false,
    max,
    format,
    legend = series.length > 1,
    height = type === 'radial' ? 220 : 200,
    center,
    className,
    style,
    ...rest
  } = componentProps

  const root = React.useRef<HTMLDivElement>(null)
  const width = useWidth(root)
  const gradientId = React.useId().replace(/:/g, '')
  const [drawn, setDrawn] = React.useState(false)
  const [active, setActive] = React.useState<number | null>(null)

  // One frame after mount, so the entrance has a starting state to leave.
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setDrawn(true))
    return () => cancelAnimationFrame(frame)
  }, [])

  const show = (n: number) => (format ? format(n) : numberFormat.format(n))
  const tones: ChartTone[] = series.map((s, i) => s.tone ?? DEFAULT_TONES[i % DEFAULT_TONES.length] ?? 'interactive')
  const valueOf = (row: ChartRow | undefined, key: string) => {
    const v = row?.[key]
    return typeof v === 'number' && Number.isFinite(v) ? v : 0
  }
  const category = (row: ChartRow, i: number) => (x !== undefined ? String(row[x] ?? '') : String(i + 1))

  // -- the scale -----------------------------------------------------------
  const totals = data.map((row) =>
    stacked ? series.reduce((sum, s) => sum + valueOf(row, s.key), 0) : Math.max(0, ...series.map((s) => valueOf(row, s.key))),
  )
  const dataTop = type === 'radial' ? 0 : Math.max(0, ...totals)
  const ticks = type === 'radial' ? [] : niceTicks(max ?? dataTop)
  const top = ticks[ticks.length - 1] ?? 1

  // -- plot geometry, in pixels ----------------------------------------------
  // Room for the tick labels, which are the scale's 14px caption (GSUI-292):
  // "1,000" is about 34px wide at 14, so the axis sits 48px in; a weekday
  // needs 30px below the plot, and half of one past the last point on a line.
  const pad = { top: 8, right: 18, bottom: 30, left: 48 }
  const plotW = Math.max(40, width - pad.left - pad.right)
  const plotH = Math.max(40, height - pad.top - pad.bottom)
  const yOf = (v: number) => pad.top + plotH - (top > 0 ? (v / top) * plotH : 0)
  const band = data.length > 0 ? plotW / data.length : plotW
  const xCentre = (i: number) =>
    type === 'bar' ? pad.left + band * i + band / 2 : pad.left + (data.length > 1 ? (plotW / (data.length - 1)) * i : plotW / 2)
  // Thin the category labels until they fit: roughly one per 44px.
  const labelEvery = Math.max(1, Math.ceil((data.length * 44) / plotW))

  const move = (next: number) => setActive(Math.max(0, Math.min(data.length - 1, next)))
  const onKeyDown = (event: React.KeyboardEvent) => {
    const count = type === 'radial' ? series.length : data.length
    if (count === 0) return
    const current = active ?? -1
    const keys: Record<string, number> = { ArrowRight: current + 1, ArrowDown: current + 1, ArrowLeft: current - 1, ArrowUp: current - 1, Home: 0, End: count - 1 }
    if (event.key in keys) {
      event.preventDefault()
      setActive(Math.max(0, Math.min(count - 1, keys[event.key] ?? 0)))
    } else if (event.key === 'Escape') {
      setActive(null)
    }
  }
  const onPointer = (event: React.PointerEvent<SVGRectElement>) => {
    if (type === 'radial' || data.length === 0) return
    const bounds = event.currentTarget.getBoundingClientRect()
    const fraction = (event.clientX - bounds.left) / Math.max(1, bounds.width)
    const index = type === 'bar' ? Math.floor(fraction * data.length) : Math.round(fraction * (data.length - 1))
    move(index)
  }

  // -- what the point in focus says ------------------------------------------
  const describe = (i: number): { title: string; lines: Array<[string, string, ChartTone]> } => {
    const tone = (j: number): ChartTone => tones[j] ?? 'interactive'
    if (type === 'radial') {
      const s = series[i]
      return s ? { title: s.label, lines: [[s.label, show(valueOf(data[0], s.key)), tone(i)]] } : { title: '', lines: [] }
    }
    const row = data[i] ?? {}
    return { title: category(row, i), lines: series.map((s, j) => [s.label, show(valueOf(row, s.key)), tone(j)]) }
  }
  const focused = active !== null ? describe(active) : null
  const announcement = focused ? copy['chart.point'](focused.title, focused.lines.map(([l, v]) => `${l} ${v}`).join(', ')) : ''

  const drawnStyle = { '--gs-chart-drawn': drawn ? 1 : 0 } as React.CSSProperties

  // -- the marks ------------------------------------------------------------
  let marks: React.ReactNode = null
  if (type === 'bar') {
    const groupW = band * 0.72
    const barW = stacked ? groupW : groupW / Math.max(1, series.length)
    marks = data.map((row, i) => {
      let base = 0
      return (
        <g key={i} data-gs-scope="chart" data-gs-part="series" data-gs-active={active === i ? 'true' : undefined}>
          {series.map((s, j) => {
            const v = valueOf(row, s.key)
            const y0 = stacked ? base : 0
            const y1 = y0 + v
            if (stacked) base = y1
            const left = pad.left + band * i + (band - groupW) / 2 + (stacked ? 0 : barW * j)
            const isTop = !stacked || j === series.length - 1
            return (
              <rect
                key={s.key}
                className="gs-chart__bar"
                data-gs-scope="chart" data-gs-part="value"
                data-gs-animates="motion"
                x={left + (stacked ? 0 : 1)}
                y={yOf(y1)}
                width={Math.max(1, barW - (stacked ? 0 : 2))}
                height={Math.max(0, yOf(y0) - yOf(y1))}
                rx={isTop ? Math.min(4, barW / 4) : 0}
                style={{ color: toneVar(tones[j] ?? 'interactive') }}
              />
            )
          })}
        </g>
      )
    })
  } else if (type === 'line' || type === 'area') {
    let below = data.map(() => 0)
    const layers = series.map((s, j) => {
      const lower = below
      const upper = data.map((row, i) => (stacked ? (lower[i] ?? 0) : 0) + valueOf(row, s.key))
      below = upper
      const upperPoints = upper.map((v, i) => [xCentre(i), yOf(v)] as [number, number])
      const bottom = (stacked ? lower : data.map(() => 0)).map((v, i) => [xCentre(i), yOf(v)] as [number, number])
      return { s, j, upperPoints, bottom }
    })
    marks = (
      <>
        {type === 'area' && (
          <defs>
            {layers.map(({ s, j }) => (
              <linearGradient key={s.key} id={`${gradientId}-${j}`} x1="0" y1="0" x2="0" y2="1" style={{ color: toneVar(tones[j] ?? 'interactive') }}>
                <stop offset="5%" className="gs-chart__stop" stopOpacity={0.55} />
                <stop offset="95%" className="gs-chart__stop" stopOpacity={0.05} />
              </linearGradient>
            ))}
          </defs>
        )}
        {/* Drawn last series first, so a stacked area's lower bands sit on top of the upper fills. */}
        {[...layers].reverse().map(({ s, j, upperPoints: upper, bottom }) => (
          <g key={s.key} data-gs-scope="chart" data-gs-part="series" style={{ color: toneVar(tones[j] ?? 'interactive') }}>
            {type === 'area' && (
              <path
                className="gs-chart__area"
                data-gs-animates="motion"
                d={`${linePath(upper, curve)}L${bottom[bottom.length - 1]?.[0] ?? 0},${bottom[bottom.length - 1]?.[1] ?? 0}${linePath([...bottom].reverse(), curve).replace(/^M/, 'L')}Z`}
                fill={`url(#${gradientId}-${j})`}
                style={{ transformOrigin: `0 ${pad.top + plotH}px` }}
              />
            )}
            <path className="gs-chart__line" data-gs-scope="chart" data-gs-part="value" data-gs-animates="motion" d={linePath(upper, curve)} pathLength={1} />
            {(dots || active !== null) &&
              upper.map(([cx, cy], i) =>
                dots || active === i ? (
                  <circle
                    key={i}
                    className="gs-chart__point"
                    data-gs-scope="chart" data-gs-part="point"
                    data-gs-active={active === i ? 'true' : undefined}
                    cx={cx}
                    cy={cy}
                    r={active === i ? 5 : 3.5}
                  />
                ) : null,
              )}
          </g>
        ))}
      </>
    )
  } else {
    // radial: concentric rings, one per series, or one ring shared when stacked.
    const size = Math.min(width, height)
    const cx = width / 2
    const cy = height / 2
    const thickness = Math.max(8, Math.min(18, size / (stacked ? 9 : 5 + series.length * 2)))
    const outer = size / 2 - thickness / 2 - 2
    const ringMax = max ?? (stacked ? series.reduce((sum, s) => sum + valueOf(data[0], s.key), 0) : Math.max(1, ...series.map((s) => valueOf(data[0], s.key))))
    let start = 0
    marks = series.map((s, j) => {
      const fraction = Math.max(0, Math.min(1, valueOf(data[0], s.key) / Math.max(1, ringMax)))
      const r = stacked ? outer : outer - j * (thickness + 4)
      const from = stacked ? start : 0
      if (stacked) start += fraction
      return (
        <g key={s.key} data-gs-scope="chart" data-gs-part="series" data-gs-active={active === j ? 'true' : undefined} style={{ color: toneVar(tones[j] ?? 'interactive') }}>
          {(!stacked || j === 0) && <circle className="gs-chart__track" data-gs-scope="chart" data-gs-part="track" cx={cx} cy={cy} r={r} strokeWidth={thickness} />}
          {fraction > 0 && (
            <path
              className="gs-chart__ring"
              data-gs-scope="chart" data-gs-part="value"
              data-gs-animates="motion"
              d={arcPath(cx, cy, r, from, from + fraction)}
              pathLength={1}
              strokeWidth={thickness}
            />
          )}
        </g>
      )
    })
  }

  const tooltipLeft =
    active === null
      ? 0
      : type === 'radial'
        ? width / 2
        : Math.max(60, Math.min(width - 60, xCentre(active)))

  return (
    <div
      {...rest}
      ref={root}
      className={['gs-chart', className].filter(Boolean).join(' ')}
      style={{ ...style, ...drawnStyle }}
      data-gs-component="chart"
      data-gs-presentation={type}
      data-gs-stacked={stacked ? 'true' : undefined}
      role="figure"
      aria-label={label}
    >
      <div
        className="gs-chart__plot"
        data-gs-scope="chart" data-gs-part="plot"
        tabIndex={0}
        role="group"
        aria-roledescription={copy['chart.roledescription']}
        aria-label={copy['chart.plotLabel'](label)}
        onKeyDown={onKeyDown}
        onBlur={() => setActive(null)}
        onPointerLeave={() => setActive(null)}
      >
        <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`} aria-hidden="true" focusable="false">
          {type !== 'radial' && (
            <g data-gs-scope="chart" data-gs-part="axis">
              {ticks.map((t) => (
                <g key={t}>
                  <line className="gs-chart__grid" x1={pad.left} x2={width - pad.right} y1={yOf(t)} y2={yOf(t)} />
                  <text className="gs-chart__tick" x={pad.left - 6} y={yOf(t)} dy="0.32em" textAnchor="end">
                    {show(t)}
                  </text>
                </g>
              ))}
              {data.map((row, i) =>
                i % labelEvery === 0 ? (
                  <text key={i} className="gs-chart__tick" x={xCentre(i)} y={height - 8} textAnchor="middle">
                    {category(row, i)}
                  </text>
                ) : null,
              )}
            </g>
          )}
          {marks}
          {type !== 'radial' && active !== null && type !== 'bar' && (
            <line className="gs-chart__cursor" x1={xCentre(active)} x2={xCentre(active)} y1={pad.top} y2={pad.top + plotH} />
          )}
          {type !== 'radial' && (
            <rect
              className="gs-chart__hit"
              x={pad.left}
              y={pad.top}
              width={plotW}
              height={plotH}
              onPointerMove={onPointer}
              onPointerDown={onPointer}
            />
          )}
        </svg>
        {type === 'radial' && center !== undefined && (
          <div className="gs-chart__center" data-gs-scope="chart" data-gs-part="center" aria-hidden="true">
            {center}
          </div>
        )}
        {focused && (
          <div className="gs-chart__tooltip" data-gs-scope="chart" data-gs-part="tooltip" aria-hidden="true" style={{ left: tooltipLeft }}>
            <p className="gs-chart__tooltip-title">{focused.title}</p>
            {focused.lines.map(([name, value, tone]) => (
              <p key={name} className="gs-chart__tooltip-row">
                <span className="gs-chart__swatch" style={{ color: toneVar(tone) }} />
                <span className="gs-chart__tooltip-name">{name}</span>
                <span className="gs-chart__tooltip-value">{value}</span>
              </p>
            ))}
          </div>
        )}
        <span className="gs-chart__hidden" data-gs-scope="chart" data-gs-part="announcement" aria-live="polite">
          {announcement}
        </span>
      </div>

      {legend && (
        <ul className="gs-chart__legend" data-gs-scope="chart" data-gs-part="legend" aria-hidden="true">
          {series.map((s, j) => (
            <li key={s.key}>
              <span className="gs-chart__swatch" style={{ color: toneVar(tones[j] ?? 'interactive') }} />
              {s.label}
            </li>
          ))}
        </ul>
      )}

      <div className="gs-chart__hidden">
      <table>
        <caption>{copy['chart.tableCaption'](label)}</caption>
        <thead>
          <tr>
            <th scope="col">{type === 'radial' ? copy['chart.seriesHeading'] : (x ?? copy['chart.pointHeading'])}</th>
            {type === 'radial' ? <th scope="col">{copy['chart.valueHeading']}</th> : series.map((s) => <th key={s.key} scope="col">{s.label}</th>)}
          </tr>
        </thead>
        <tbody>
          {type === 'radial'
            ? series.map((s) => (
                <tr key={s.key}>
                  <th scope="row">{s.label}</th>
                  <td>{show(valueOf(data[0], s.key))}</td>
                </tr>
              ))
            : data.map((row, i) => (
                <tr key={i}>
                  <th scope="row">{category(row, i)}</th>
                  {series.map((s) => (
                    <td key={s.key}>{show(valueOf(row, s.key))}</td>
                  ))}
                </tr>
              ))}
        </tbody>
      </table>
      </div>
    </div>
  )
}

export interface ChartCardProps extends Omit<React.HTMLAttributes<HTMLElement>, 'title'> {
  /** The card's heading. */
  title: React.ReactNode
  /** One line under the heading, e.g. the period the chart covers. */
  description?: React.ReactNode
  /** A line under the chart, e.g. a trend in words. */
  footer?: React.ReactNode
  children: React.ReactNode
}

/** The card shadcn puts a chart in: heading, one line, the chart, a footer line. */
export function ChartCard({ title, description, footer, children, className, ...rest }: ChartCardProps) {
  return (
    <section {...rest} className={['gs-chart-card', className].filter(Boolean).join(' ')} data-gs-scope="chart" data-gs-part="panel">
      <header className="gs-chart-card__header">
        <h3 className="gs-chart-card__title" data-gs-scope="chart" data-gs-part="label">
          {title}
        </h3>
        {description && (
          <p className="gs-chart-card__description" data-gs-scope="chart" data-gs-part="detail">
            {description}
          </p>
        )}
      </header>
      {children}
      {footer && (
        <p className="gs-chart-card__footer" data-gs-scope="chart" data-gs-part="note">
          {footer}
        </p>
      )}
    </section>
  )
}

/* Chart. Every value comes from a token; nothing here is a literal colour,
   typeface or duration. A series' colour arrives as `color` on its element,
   set by the component to a `--gs-color-*-solid` token, so every mark below
   paints in `currentColor` and follows the Studio palette bridge. */

/* Registered so the entrance can transition. The component moves it from 0 to
   1 one frame after mount; bars scale, lines draw and rings sweep from it. */
@property --gs-chart-drawn {
  syntax: '<number>';
  inherits: true;
  initial-value: 0;
}

.gs-chart {
  position: relative;
  display: grid;
  gap: var(--gs-space-2);
  min-width: 0;
  color: var(--gs-color-ink);
  font-family: var(--gs-type-body-font-family);
  font-variant-numeric: tabular-nums;
}

.gs-chart__plot {
  position: relative;
  min-width: 0;
  border-radius: var(--gs-radius-md);
  outline: none;
}

.gs-chart__plot:focus-visible {
  box-shadow: 0 0 0 var(--gs-stroke-focus) var(--gs-color-interactive-solid);
}

.gs-chart__plot > svg {
  display: block;
  overflow: visible;
}

/* -- axes ----------------------------------------------------------------- */

.gs-chart__grid {
  stroke: var(--gs-color-edge-solid);
  stroke-width: var(--gs-stroke-hairline);
  stroke-dasharray: 3 3;
}

.gs-chart__tick {
  fill: var(--gs-color-ink-secondary-solid);
  font-size: var(--gs-type-caption-font-size);
  font-family: var(--gs-type-caption-font-family);
  font-variant-numeric: tabular-nums;
}

.gs-chart__cursor {
  stroke: var(--gs-color-ink-secondary-solid);
  stroke-width: var(--gs-stroke-hairline);
}

.gs-chart__hit {
  fill: transparent;
  cursor: crosshair;
}

/* -- marks ---------------------------------------------------------------- */
/* Each moves once, from the baseline or the start of its line, over the fill
   motion token. `data-gs-animates="motion"` on every one of them is what the
   token file stops dead under reduced motion. */

.gs-chart__bar {
  fill: currentColor;
  transform-box: fill-box;
  transform-origin: center bottom;
  transform: scaleY(var(--gs-chart-drawn));
  transition: transform var(--gs-motion-fill) var(--gs-motion-ease-fill);
}

.gs-chart [data-gs-part='series'][data-gs-active='true'] .gs-chart__bar,
.gs-chart[data-gs-presentation='bar'] [data-gs-part='series'][data-gs-active='true'] {
  filter: brightness(1.15);
}

.gs-chart__line {
  fill: none;
  stroke: currentColor;
  stroke-width: calc(var(--gs-stroke-ui, var(--gs-stroke-hairline)) + 1px);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-dasharray: 1;
  stroke-dashoffset: calc(1 - var(--gs-chart-drawn));
  transition: stroke-dashoffset var(--gs-motion-fill) var(--gs-motion-ease-fill);
}

.gs-chart__area {
  transform-box: view-box;
  transform: scaleY(var(--gs-chart-drawn));
  transition: transform var(--gs-motion-fill) var(--gs-motion-ease-fill);
}

.gs-chart__stop {
  stop-color: currentColor;
}

.gs-chart__point {
  fill: var(--gs-color-surface-solid);
  stroke: currentColor;
  stroke-width: 2;
}

.gs-chart__point[data-gs-active='true'] {
  fill: currentColor;
}

.gs-chart__track {
  fill: none;
  stroke: var(--gs-color-edge-solid);
}

.gs-chart__ring {
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-dasharray: 1;
  stroke-dashoffset: calc(1 - var(--gs-chart-drawn));
  transition: stroke-dashoffset var(--gs-motion-fill) var(--gs-motion-ease-fill);
}

.gs-chart [data-gs-part='series'][data-gs-active='true'] .gs-chart__ring {
  filter: brightness(1.15);
}

.gs-chart__center {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  pointer-events: none;
  text-align: center;
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-stat-font-size);
  font-weight: var(--gs-type-stat-font-weight);
}

/* -- tooltip and legend --------------------------------------------------- */

.gs-chart__tooltip {
  position: absolute;
  top: 0;
  transform: translateX(-50%);
  min-width: 7.5rem;
  display: grid;
  gap: var(--gs-space-1);
  padding: var(--gs-space-2) var(--gs-space-3);
  border-radius: var(--gs-radius-md);
  border: var(--gs-stroke-hairline) solid var(--gs-color-edge-solid);
  background: var(--gs-color-surface-raised-solid);
  box-shadow: 0 4px 16px var(--gs-color-shadow-solid);
  font-size: var(--gs-type-caption-font-size);
  pointer-events: none;
}

.gs-chart__tooltip p {
  margin: 0;
}

.gs-chart__tooltip-title {
  font-weight: var(--gs-type-label-font-weight);
}

.gs-chart__tooltip-row {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
}

.gs-chart__tooltip-name {
  flex: 1;
  color: var(--gs-color-ink-secondary-solid);
}

.gs-chart__tooltip-value {
  font-variant-numeric: tabular-nums;
  font-weight: var(--gs-type-label-font-weight);
}

.gs-chart__swatch {
  display: inline-block;
  width: 0.625rem;
  height: 0.625rem;
  border-radius: var(--gs-radius-sm);
  background: currentColor;
  flex: none;
}

.gs-chart__legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: var(--gs-space-2) var(--gs-space-4);
  margin: 0;
  padding: 0;
  list-style: none;
  font-size: var(--gs-type-caption-font-size);
  color: var(--gs-color-ink-secondary-solid);
}

.gs-chart__legend li {
  display: inline-flex;
  align-items: center;
  gap: var(--gs-space-2);
}

/* Present for a screen reader, absent for the eye. */
.gs-chart__hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* -- the card ------------------------------------------------------------- */

.gs-chart-card {
  display: grid;
  gap: var(--gs-space-3);
  min-width: 0;
  padding: var(--gs-space-4);
  border-radius: var(--gs-radius-lg);
  border: var(--gs-stroke-hairline) solid var(--gs-color-edge-solid);
  background: var(--gs-color-surface-solid);
  color: var(--gs-color-ink);
}

.gs-chart-card__header {
  display: grid;
  gap: var(--gs-space-1);
}

.gs-chart-card__title {
  margin: 0;
  font-family: var(--gs-type-title-font-family);
  font-size: var(--gs-type-title-font-size);
  font-weight: var(--gs-type-title-font-weight);
}

.gs-chart-card__description,
.gs-chart-card__footer {
  margin: 0;
  font-size: var(--gs-type-caption-font-size);
  color: var(--gs-color-ink-secondary-solid);
}
